7	export function ago(iso, now = Date.now()) {
8	  const minutes = Math.floor(Math.max(0, now - Date.parse(iso)) / 60000);
9	  const count = (n, unit) => `${n} ${unit}${n === 1 ? '' : 's'} ago`;
10	  if (!Number.isFinite(minutes)) return 'a while ago';
11	  if (minutes < 1) return 'just now';
12	  if (minutes < 60) return count(minutes, 'minute');
13	  const hours = Math.floor(minutes / 60);
14	  if (hours < 24) return count(hours, 'hour');
15	  const days = Math.floor(hours / 24);
16	  if (days === 1) return 'yesterday';
17	  if (days < 30) return count(days, 'day');
18	  if (days < 365) return count(Math.floor(days / 30), 'month');
19	  return count(Math.floor(days / 365), 'year');
20	}
